<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??'create'; if($action==='create'){ $u=trim($_POST['username']??''); $p=$_POST['password']??''; $role=$_POST['role']??'cashier'; if(strlen($u)<3||strlen($p)<6)throw new RuntimeException('Username must be 3+ characters and password 6+ characters.'); if(!in_array($role,['cashier','pharmacist','manager','admin'],true))throw new RuntimeException('Invalid role.'); $db->prepare('INSERT INTO users(username,password_hash,role,active) VALUES(?,?,?,1)')->execute([$u,password_hash($p,PASSWORD_DEFAULT),$role]); $message='User created successfully.'; } elseif($action==='toggle'){ $id=(int)$_POST['id']; $db->prepare('UPDATE users SET active=IF(active=1,0,1) WHERE id=?')->execute([$id]); $message='User status updated.'; } elseif($action==='reset'){ $id=(int)$_POST['id']; $p=$_POST['password']??''; if(strlen($p)<6)throw new RuntimeException('New password must be at least 6 characters.'); $db->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),$id]); $message='Password changed successfully.'; } elseif($action==='role'){ $id=(int)$_POST['id']; $role=$_POST['role']??'cashier'; if(!in_array($role,['cashier','pharmacist','manager','admin'],true))throw new RuntimeException('Invalid role.'); $db->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$id]); $message='Role updated.'; }}catch(Throwable $e){$error=$e->getMessage();}} $rows=$db->query('SELECT id,username,role,active,created_at FROM users ORDER BY username')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="style.css"><style>.user-actions{display:flex;gap:7px;flex-wrap:wrap}.user-actions form{display:flex;gap:5px;align-items:center}.user-actions input,.user-actions select{width:auto;padding:7px}.role-badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:11px;font-weight:700}.status-active{color:#166534;font-weight:700}.status-disabled{color:#991b1b;font-weight:700}.small-btn{padding:7px 10px;font-size:12px}.security-note{padding:12px 14px;border-radius:10px;background:#f8fafc;margin-bottom:15px;color:#475569;font-size:13px}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">STAFF ACCESS</div><h1>Users & Roles</h1><p>Manage staff accounts, passwords, roles and access status.</p></div></div><?php if($error):?><div class="alert">⚠ <?=e($error)?></div><?php endif;?><?php if($message):?><div class="success">✓ <?=e($message)?></div><?php endif;?><section class="panel"><h2>Add User</h2><div class="security-note">🔐 Use a unique password for every staff account. Admin and manager accounts should only be given to trusted staff.</div><form method="post" class="grid"><input type="hidden" name="action" value="create"><label>Username<input name="username" required autocomplete="off"></label><label>Password<input type="password" name="password" required minlength="6" autocomplete="new-password"></label><label>Role<select name="role"><option value="cashier">Cashier</option><option value="pharmacist">Pharmacist</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label><button class="btn">Create User</button></form></section><section class="panel"><h2>Staff Accounts</h2><table><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['username'])?></b></td><td><form method="post"><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="role" onchange="this.form.submit()"><option value="cashier" <?=$r['role']==='cashier'?'selected':''?>>Cashier</option><option value="pharmacist" <?=$r['role']==='pharmacist'?'selected':''?>>Pharmacist</option><option value="manager" <?=$r['role']==='manager'?'selected':''?>>Manager</option><option value="admin" <?=$r['role']==='admin'?'selected':''?>>Admin</option></select></form></td><td class="<?=$r['active']?'status-active':'status-disabled'?>"><?=$r['active']?'Active':'Disabled'?></td><td><?=e($r['created_at'])?></td><td><div class="user-actions"><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small-btn" type="submit"><?=$r['active']?'Disable':'Enable'?></button></form><form method="post" onsubmit="return confirm('Change this user password?')"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="password" name="password" minlength="6" placeholder="New password" required><button class="btn small-btn" type="submit">Change Password</button></form></div></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Recommended Access</h2><table><tr><th>Role</th><th>Recommended use</th></tr><tr><td><span class="role-badge">Cashier</span></td><td>POS sales and normal customer payments.</td></tr><tr><td><span class="role-badge">Pharmacist</span></td><td>POS plus medicine/inventory operations.</td></tr><tr><td><span class="role-badge">Manager</span></td><td>Purchases, suppliers, expenses, returns and reports.</td></tr><tr><td><span class="role-badge">Admin</span></td><td>Full management, users and backup/restore.</td></tr></table></section></main></body></html>